cat > src/__tmp_check.test.tsx <<'EOF'
import { describe, it, expect } from 'vitest';
import { renderToStaticMarkup } from 'react-dom/server';
import { ThemeProvider } from '@gravity-ui/uikit';
import { MarkdownField } from './MarkdownField';

const render = (value: string) =>
  renderToStaticMarkup(
    <ThemeProvider theme="light">
      <MarkdownField label="L" value={value} onUpdate={() => {}} />
    </ThemeProvider>,
  );

describe('MarkdownField', () => {
  it('renders markdown in preview', () => {
    const html = render('# Head\n\n**bold** *it* `code`\n\n- a\n- b\n\n| x | y |\n|---|---|\n| 1 | 2 |\n\n[l](https://e.com)');
    console.log(html.slice(html.indexOf('md-preview')));
    expect(html).toContain('<h1>Head</h1>');
    expect(html).toContain('<strong>bold</strong>');
    expect(html).toContain('<em>it</em>');
    expect(html).toContain('<code>code</code>');
    expect(html).toContain('<li>a</li>');
    expect(html).toContain('<table>');
    expect(html).toContain('href="https://e.com"');
  });
  it('does not render raw html', () => {
    const html = render('<script>alert(1)</script><img src=x onerror=alert(1)>');
    expect(html).not.toContain('<script>');
    expect(html).not.toContain('<img');
  });
  it('shows placeholder when empty', () => {
    expect(render('   ')).toContain('Предпросмотр появится здесь');
  });
});
EOF
timeout 200 npx vitest run src/__tmp_check.test.tsx 2>&1 | grep -v "npm warn" | tail -60; rm -f src/__tmp_check.test.tsx; git status --short

